write('P20.current-text-preimage.author.candidates.json',p);cfg=read(T/'P20.current-text-preimage.author.config.json');cfg['reviewId']=review;cfg['reviewPath']=str((D/'P20.current-text-preimage.author.review.jsonl').relative_to(ROOT));cfg['scope']={'label':'20 exact current whole source-bounded Flora/Fauna20 profiles, chosen bird depth, real performance duties, E1/G1 author candidates','goalIds':ids};write('P20.current-text-preimage.author.config.json',cfg)
