 out=ret/f'{gate}20.exact.rows.jsonl';out.write_text(''.join(lines));conf=read(T/f'{gate}20.current.native.config.json');conf['reviewPath']=str(out.relative_to(ROOT));conf['scope']={'label':'20 unchanged Flora/Fauna goals; retain valid A/M including flower3cards and actual visibility checks','leafGoalIds':ids}
